const dictionaries: Record<string, Dictionary> = { fr, es, de, it, pt, nl, ru, uk, pl, tr, ja, ko, zh };

/** Languages with a translation, besides English. */
export const supportedLanguages = ["en", ...Object.keys(dictionaries)];

function currentLanguage(): string {
    const store = findStore<{ locale?: string; }>("LocaleStore");
    return (store?.locale ?? "en").toLowerCase().split("-")[0];
}

/** Translates a UI string with Discord's language, falling back to English. {name} placeholders are filled from params. */
export function t(key: Key, params?: Record<string, string | number>): string {
    const text = dictionaries[currentLanguage()]?.[key] ?? en[key];
    return params ? text.replace(/\{(\w+)\}/g, (_, name: string) => String(params[name] ?? `{${name}}`)) : text;
}
